CREATE OR REPLACE FUNCTION public.koe_reconcile_memberships(p_project text, p_catenda_project uuid, p_members jsonb, p_started_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE m JSONB; v_user UUID; v_previous TIMESTAMPTZ;
BEGIN
    IF jsonb_typeof(p_members) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'Expected complete membership snapshot';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('membership:' || p_project, 0));
    IF NOT EXISTS (SELECT 1 FROM public.catenda_project_configs
        WHERE internal_project_id = p_project AND catenda_project_id = p_catenda_project AND is_active) THEN
        RAISE EXCEPTION 'Project mapping changed';
    END IF;
    SELECT synced_at INTO v_previous FROM public.app_membership_sync WHERE project_id = p_project;
    IF v_previous >= p_started_at THEN RETURN false; END IF;
    IF p_started_at > now() + interval '30 seconds' THEN RAISE EXCEPTION 'Invalid snapshot time'; END IF;
    IF (SELECT count(*) FROM jsonb_array_elements(p_members)) <>
       (SELECT count(DISTINCT value->>'subject') FROM jsonb_array_elements(p_members)) THEN
        RAISE EXCEPTION 'Duplicate or missing subject';
    END IF;
    FOR m IN SELECT value FROM jsonb_array_elements(p_members) ORDER BY value->>'subject' LOOP
        IF m->>'role' IS NULL OR m->>'role' NOT IN ('admin', 'member') THEN
            RAISE EXCEPTION 'Invalid membership role';
        END IF;
        v_user := public.koe_resolve_identity('catenda', 'https://api.catenda.com',
            m->>'subject', coalesce(m->>'email', ''), coalesce(m->>'name', ''));
        INSERT INTO public.app_project_memberships
            (project_id, user_id, catenda_subject, user_email, display_name, role)
        VALUES (p_project, v_user, m->>'subject', m->>'email', m->>'name', m->>'role')
        ON CONFLICT (project_id, user_id) DO UPDATE SET
            user_email = excluded.user_email, display_name = excluded.display_name,
            role = excluded.role, active = true, updated_at = now();
    END LOOP;
    UPDATE public.app_project_memberships SET active = false, updated_at = now()
        WHERE project_id = p_project AND active AND catenda_subject NOT IN
            (SELECT value->>'subject' FROM jsonb_array_elements(p_members));
    INSERT INTO public.app_membership_sync(project_id, catenda_project_id, synced_at)
        VALUES (p_project, p_catenda_project, p_started_at)
        ON CONFLICT (project_id) DO UPDATE SET
            catenda_project_id = excluded.catenda_project_id, synced_at = excluded.synced_at;
    RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.koe_register_project(p_project_id text, p_name text, p_description text, p_organisasjon_id text, p_catenda_project_id uuid, p_library_id uuid, p_folder_id uuid DEFAULT NULL::uuid, p_topic_board_id uuid DEFAULT NULL::uuid, p_teams jsonb DEFAULT NULL::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
    BEGIN
        IF p_organisasjon_id IS NULL OR btrim(p_organisasjon_id) = '' THEN
            RAISE EXCEPTION 'organisasjon_id er påkrevd; det finnes ingen defaultvirksomhet';
        END IF;

        INSERT INTO public.projects (
            id, name, description, organisasjon_id, is_active, created_by
        )
        VALUES (
            p_project_id,
            p_name,
            COALESCE(p_description, 'Prosjekt ' || p_name),
            btrim(p_organisasjon_id),
            TRUE,
            'admin_cli'
        )
        ON CONFLICT (id) DO UPDATE SET
            name = EXCLUDED.name,
            description = EXCLUDED.description,
            is_active = TRUE;

        INSERT INTO public.catenda_project_configs (
            internal_project_id, catenda_project_id, library_id, folder_id, is_active
        )
        VALUES (
            p_project_id, p_catenda_project_id, p_library_id, p_folder_id, TRUE
        )
        ON CONFLICT (internal_project_id) DO UPDATE SET
            catenda_project_id = EXCLUDED.catenda_project_id,
            library_id = EXCLUDED.library_id,
            folder_id = EXCLUDED.folder_id,
            is_active = TRUE;

        IF p_topic_board_id IS NOT NULL THEN
            INSERT INTO public.catenda_topic_board_configs (
                topic_board_id, internal_project_id, is_active
            )
            VALUES (
                p_topic_board_id, p_project_id, TRUE
            )
            ON CONFLICT (topic_board_id) DO UPDATE SET
                internal_project_id = EXCLUDED.internal_project_id,
                is_active = TRUE;
        END IF;

        IF p_teams IS NOT NULL THEN
            PERFORM public.koe_set_contract_teams(p_project_id, p_teams);
        END IF;

        RETURN TRUE;
    END;
    $function$

CREATE OR REPLACE FUNCTION public.koe_resolve_identity(p_provider text, p_issuer text, p_subject text, p_email text, p_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_user UUID;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(p_provider || ':' || p_issuer || ':' || p_subject, 0));
    SELECT user_id INTO v_user FROM public.app_identities
        WHERE provider = p_provider AND issuer = p_issuer AND subject = p_subject;
    IF v_user IS NULL THEN
        INSERT INTO public.app_users(email, name)
            VALUES (coalesce(p_email, ''), coalesce(p_name, ''))
            RETURNING id INTO v_user;
        INSERT INTO public.app_identities(user_id, provider, issuer, subject)
            VALUES (v_user, p_provider, p_issuer, p_subject);
    ELSE
        UPDATE public.app_users
            SET email = coalesce(nullif(p_email, ''), email),
                name = coalesce(nullif(p_name, ''), name)
            WHERE id = v_user;
    END IF;
    RETURN v_user;
END;
$function$

CREATE OR REPLACE FUNCTION public.koe_set_contract_teams(p_project text, p_teams jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
    DECLARE
        v_item JSONB;
        v_team_id UUID;
        v_role TEXT;
        v_has_bh BOOLEAN := FALSE;
        v_has_te BOOLEAN := FALSE;
    BEGIN
        PERFORM 1 FROM public.catenda_project_configs
        WHERE internal_project_id = p_project AND is_active = TRUE
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Aktivt prosjekt ikke funnet: %', p_project;
        END IF;

        IF jsonb_typeof(p_teams) IS DISTINCT FROM 'array' THEN
            RAISE EXCEPTION 'p_teams må være et JSONB array av objekter';
        END IF;

        DELETE FROM public.catenda_contract_teams
        WHERE internal_project_id = p_project;

        FOR v_item IN SELECT * FROM jsonb_array_elements(p_teams)
        LOOP
            v_team_id := (v_item->>'team_id')::UUID;
            v_role := (v_item->>'contract_role')::TEXT;

            IF v_role NOT IN ('BH', 'TE') THEN
                RAISE EXCEPTION 'Ugyldig contract_role: % (må være BH eller TE)', v_role;
            END IF;

            IF v_role = 'BH' THEN
                v_has_bh := TRUE;
            ELSIF v_role = 'TE' THEN
                v_has_te := TRUE;
            END IF;

            INSERT INTO public.catenda_contract_teams (internal_project_id, team_id, contract_role)
            VALUES (p_project, v_team_id, v_role);
        END LOOP;

        IF NOT (v_has_bh AND v_has_te) THEN
            RAISE EXCEPTION 'Både BH og TE må være representert i p_teams';
        END IF;

        RETURN TRUE;
    END;
    $function$

CREATE OR REPLACE FUNCTION public.set_catenda_project_registry_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$

